// Accept optional ?year=YYYY&week=WW from webhook, or auto-detect previous week
const input = $input.first().json;
const paramYear = input.query?.year ? parseInt(input.query.year) : null;
const paramWeek = input.query?.week ? parseInt(input.query.week) : null;

let weekStart, weekEnd, year, weekNum;

if (paramYear && paramWeek) {
  // Calculate date range from ISO week number
  year = paramYear;
  weekNum = paramWeek;
  // ISO week 1 starts on the Monday of the week containing Jan 4th
  const jan4 = new Date(year, 0, 4);
  const dayOfWeek = jan4.getDay() || 7; // Mon=1..Sun=7
  const isoWeek1Monday = new Date(jan4);
  isoWeek1Monday.setDate(jan4.getDate() - dayOfWeek + 1);
  weekStart = new Date(isoWeek1Monday);
  weekStart.setDate(isoWeek1Monday.getDate() + (weekNum - 1) * 7);
  weekEnd = new Date(weekStart);
  weekEnd.setDate(weekStart.getDate() + 6);
} else {
  // Auto: previous week (Mon-Sun)
  const now = new Date();
  const dow = now.getDay();
  weekEnd = new Date(now);
  weekEnd.setDate(now.getDate() - (dow === 0 ? 0 : dow));
  weekStart = new Date(weekEnd);
  weekStart.setDate(weekEnd.getDate() - 6);
  year = weekEnd.getFullYear();
  const jan1 = new Date(year, 0, 1);
  weekNum = Math.ceil(((weekEnd - jan1) / 86400000 + jan1.getDay() + 1) / 7);
}

const fmt = (d) => d.toISOString().split('T')[0];

return [{
  json: {
    weekStart: fmt(weekStart),
    weekEnd: fmt(weekEnd),
    year,
    week: weekNum,
    jiraBaseUrl: 'https://casaametller.atlassian.net',
    kpiApiUrl: 'http://backend:8000'
  }
}];

const issues = $('JQL Backlog Count').first().json.issues || [];
const backlogTotal = issues.length;
const dates = $('Calculate Week Range').first().json;
return [{ json: { kpi_code: 'SRV-BKL', year: dates.year, month: dates.week, value: backlogTotal, notes: `Backlog total: ${backlogTotal} tickets (setmana ${dates.week})`, workflow_id: 'jira-sdit-weekly-ops' } }];

const issues = $('JQL P1 Incidents (Sistemes)').first().json.issues || [];
const dates = $('Calculate Week Range').first().json;
if (issues.length === 0) {
  return [{ json: { kpi_code: 'SRV-P1R', year: dates.year, month: dates.week, value: 100, notes: 'Cap P1 resolt aquesta setmana', workflow_id: 'jira-sdit-weekly-ops' } }];
}
return issues.map(issue => ({ json: { issueKey: issue.key, created: issue.fields.created, resolutiondate: issue.fields.resolutiondate } }));

const slaResults = $input.all();
const dates = $('Calculate Week Range').first().json;
const TWO_HOURS_MS = 2 * 60 * 60 * 1000;
let withinTarget = 0, total = 0;
for (const item of slaResults) {
  const values = item.json.values || item.json.slaValues || [];
  const resSLA = values.find(s => (s.name || '').toLowerCase().includes('resolution') || (s.metric?.name || '').toLowerCase().includes('resolution'));
  if (resSLA) {
    total++;
    const cycle = resSLA.completedCycles?.[0] || resSLA.ongoingCycle;
    if (cycle && (cycle.elapsedTime?.millis || 0) <= TWO_HOURS_MS) withinTarget++;
  }
}
const pct = total > 0 ? Math.round((withinTarget / total) * 10000) / 100 : 100;
return [{ json: { kpi_code: 'SRV-P1R', year: dates.year, month: dates.week, value: pct, notes: `${withinTarget}/${total} P1 resolts dins 2h (setmana ${dates.week})`, workflow_id: 'jira-sdit-weekly-ops' } }];

const issues = $('JQL P1+P2 Incidents (Sistemes)').first().json.issues || [];
const dates = $('Calculate Week Range').first().json;
if (issues.length === 0) {
  return [{ json: { kpi_code: 'SRV-P12', year: dates.year, month: dates.week, value: 100, notes: 'Cap P1/P2 resolt aquesta setmana', workflow_id: 'jira-sdit-weekly-ops' } }];
}
return issues.map(issue => ({ json: { issueKey: issue.key, created: issue.fields.created, resolutiondate: issue.fields.resolutiondate } }));

const slaResults = $input.all();
const dates = $('Calculate Week Range').first().json;
const FIVE_HOURS_MS = 5 * 60 * 60 * 1000;
let withinTarget = 0, total = 0;
for (const item of slaResults) {
  const values = item.json.values || item.json.slaValues || [];
  const resSLA = values.find(s => (s.name || '').toLowerCase().includes('resolution') || (s.metric?.name || '').toLowerCase().includes('resolution'));
  if (resSLA) {
    total++;
    const cycle = resSLA.completedCycles?.[0] || resSLA.ongoingCycle;
    if (cycle && (cycle.elapsedTime?.millis || 0) <= FIVE_HOURS_MS) withinTarget++;
  }
}
const pct = total > 0 ? Math.round((withinTarget / total) * 10000) / 100 : 100;
return [{ json: { kpi_code: 'SRV-P12', year: dates.year, month: dates.week, value: pct, notes: `${withinTarget}/${total} P1+P2 resolts dins 5h (setmana ${dates.week})`, workflow_id: 'jira-sdit-weekly-ops' } }];

const issues = $('JQL Issues with Worklogs').first().json.issues || [];
const dates = $('Calculate Week Range').first().json;
const weekStartMs = new Date(dates.weekStart).getTime();
const weekEndMs = new Date(dates.weekEnd + 'T23:59:59Z').getTime();
const TARGET_SECONDS = 40 * 3600;
const byAuthor = {};
for (const issue of issues) {
  const worklogs = issue.fields?.worklog?.worklogs || [];
  for (const wl of worklogs) {
    const started = new Date(wl.started).getTime();
    if (started >= weekStartMs && started <= weekEndMs) {
      const author = wl.author?.displayName || wl.author?.emailAddress || 'unknown';
      byAuthor[author] = (byAuthor[author] || 0) + (wl.timeSpentSeconds || 0);
    }
  }
}
const authors = Object.entries(byAuthor);
if (authors.length === 0) {
  return [{ json: { kpi_code: 'SRV-TIM', year: dates.year, month: dates.week, value: 0, notes: 'Cap worklog registrat aquesta setmana', workflow_id: 'jira-sdit-weekly-ops' } }];
}
const pctPerAuthor = authors.map(([, secs]) => (secs / TARGET_SECONDS) * 100);
const avgPct = Math.round((pctPerAuthor.reduce((a, b) => a + b, 0) / pctPerAuthor.length) * 100) / 100;
const avgHours = Math.round((authors.reduce((sum, [, s]) => sum + s, 0) / authors.length / 3600) * 10) / 10;
return [{ json: { kpi_code: 'SRV-TIM', year: dates.year, month: dates.week, value: avgPct, notes: `${authors.length} persones, mitjana ${avgHours}h/40h (setmana ${dates.week})`, workflow_id: 'jira-sdit-weekly-ops' } }];

// Input 0 = Changes Total, Input 1 = Changes No Due Date
const items = $input.all();
const totalChanges = (items[0]?.json?.issues || []).length;
const noDueDate = (items[1]?.json?.issues || []).length;
const dates = $('Calculate Week Range').first().json;
const withDueDate = totalChanges - noDueDate;
const pct = totalChanges > 0 ? Math.round((withDueDate / totalChanges) * 10000) / 100 : 100;
return [{ json: { kpi_code: 'SRV-CHG', year: dates.year, month: dates.week, value: pct, notes: `${withDueDate}/${totalChanges} changes amb Due Date (setmana ${dates.week})`, workflow_id: 'jira-sdit-weekly-ops' } }];
